CREATE VIEW top_sellers (product, sold) AS
SELECT p.name, SUM(s.quantity)
FROM sales s
JOIN products p ON p.id = s.product_id
GROUP BY p.id, p.name;

SELECT * FROM top_sellers WHERE sold >= 4 ORDER BY sold DESC, product;

