challenges.solution:
WITH RECURSIVE n(x) AS (
  SELECT 1
  UNION ALL
  SELECT x + 1 FROM n WHERE x < (SELECT COUNT(*) FROM products)
)
SELECT x FROM n ORDER BY x;

WITH RECURSIVE days(day) AS (
  SELECT date(MAX(sold_on), '+1 day') FROM sales
  UNION ALL
  SELECT date(day, '+1 day') FROM days
)
SELECT day FROM days LIMIT 5;

WITH RECURSIVE d(step, amount) AS (
  SELECT 0, MIN(price) FROM products
  UNION ALL
  SELECT step + 1, amount * 2 FROM d WHERE amount * 2 <= 100
)
SELECT step, amount FROM d ORDER BY step;

WITH RECURSIVE g(year, target) AS (
  SELECT 2026, q4 FROM targets WHERE staff_id = 2
  UNION ALL
  SELECT year + 1, target * 1.1 FROM g WHERE year < 2030
)
SELECT year, ROUND(target) AS target FROM g ORDER BY year;

